#!/usr/bin/env bash
set -euo pipefail
umask 077
VERSION="1.0.0-rc4"
EXPECTED_SHA256="f4122f235665bab7e3695de417c7528c998adc96ffeca351153e360f74e1d45b"
usage() {
  cat <<'HADS_NEXT_USAGE'
HADS Next 1.0.0-rc4 — samostatná vývojová aplikace, nikoli produkční RC.
Použití:
  bash HADS_Next_install_1.0.0-rc4.sh --verify
  bash HADS_Next_install_1.0.0-rc4.sh --extract-only /absolutni/novy-adresar
  bash HADS_Next_install_1.0.0-rc4.sh --install-dev
  bash HADS_Next_install_1.0.0-rc4.sh --upgrade-rc3
Nová instalace přidá local_hads_next_practical. Výslovný --upgrade-rc3 aktualizuje jen ověřený Next RC3 přes nativní Supervisor update; zachová /data a vyžádá nativní částečnou zálohu. Starý Hermes 2.0.0-rc3 se nemění.
Původní Hermes je součástí balíčku. AI i vlastní testovací opravný katalog vyžadují výslovný souhlas. Obecné produkční zápisy jsou zakázané. Živá HAOS přejímka čeká.
HADS_NEXT_USAGE
}
MODE="${1:-}"
case "$MODE" in
  --help) [ "$#" = 1 ] || exit 2; usage; exit 0 ;;
  --verify|--install-dev|--upgrade-rc3) [ "$#" = 1 ] || { usage; exit 2; } ;;
  --extract-only) [ "$#" = 2 ] || { usage; exit 2; } ;;
  *) usage; exit 2 ;;
esac
command -v python3 >/dev/null || { echo 'Chybí python3 v terminálové aplikaci. Podrobnosti jsou v návodu DOCS.md.' >&2; exit 1; }
command -v base64 >/dev/null || { echo 'Chybí base64.' >&2; exit 1; }
STAGING="$(mktemp -d /tmp/hads-next-install.XXXXXX)"
cleanup() {
  case "$STAGING" in /tmp/hads-next-install.*) rm -rf -- "$STAGING" ;; esac
}
trap cleanup EXIT
base64 -d > "$STAGING/payload.tar.gz" <<'HADS_NEXT_PAYLOAD'
